import { mkdirSync, writeFileSync } from 'node:fs';
import { expect, test } from '@playwright/test';
import { BUDGETS, type Budget } from './budgets';

/** Documents of SPEC NFR-1.2 (generated by the demo page in bench mode). */
const DOCUMENTS = [
  'paragraphs-1k',
  'paragraphs-10k',
  'paragraphs-50k',
  'nested-list',
  'table-large',
];
const TYPING_ITERATIONS = 200;
const EXPORT_RUNS = 5;
const MOVE_ITERATIONS = 50;
const KEYS = 40;
/** Searches (ADR 0004): a frequent word (1000+ matches) and a rare phrase spread everywhere. */
const SEARCH_FREQUENT = 'dolor';
const SEARCH_RARE = 'velit esse lorem';
/** Real key presses: one every 33 ms, like a held key or a fast typist. */
const KEY_DELAY = 33;
/** Event Timing reports only durations from this value up; faster keys count as this value. */
const EVENT_THRESHOLD = 16;

/** Metrics of one document, in milliseconds (heap in MB). */
type Result = Budget & {
  typingMedian: number;
  moveBlockMedian: number;
  /** Real key press to next paint (Event Timing), informative: median and p95. */
  keyToPaintMedian: number;
  keyToPaintP95: number;
  heapMB: number | null;
  /** Informative (ADR 0004): setting a search, and typing in the middle while it is active. */
  searchFrequent: number;
  searchRare: number;
  searchTypingP95: number;
};

const results: Record<string, Result> = {};

/** Nearest-rank percentile of `values` (`p` in 0–100). */
function percentile(values: number[], p: number): number {
  const sorted = [...values].sort((a, b) => a - b);
  return sorted[Math.max(0, Math.ceil((p / 100) * sorted.length) - 1)] ?? Number.NaN;
}

function round(value: number): number {
  return Math.round(value * 100) / 100;
}

test.describe.configure({ mode: 'serial' });

for (const name of DOCUMENTS) {
  test(name, async ({ page }) => {
    await page.goto('/demo/?bench');
    await page.waitForFunction(() => window.__stilo !== undefined);
    const raw = await page.evaluate(
      ({ name, typing, exports, moves, frequent, rare }) => {
        const api = window.__stilo!;
        const load = api.load(name);
        const heap = api.heapSize();
        const getHTML = Array.from({ length: exports }, () => api.getHTML());
        const latency = [0, 0.5, 1].map((fraction) => api.typing(fraction, typing));
        const moveBlock = api.moveBlock(moves);
        const searchRare = api.search(rare);
        const searchFrequent = api.search(frequent);
        const searchTyping = api.typing(0.5, typing);
        api.search('');
        return {
          load,
          heap,
          getHTML,
          latency,
          moveBlock,
          searchRare,
          searchFrequent,
          searchTyping,
        };
      },
      {
        ...{ name, typing: TYPING_ITERATIONS, exports: EXPORT_RUNS, moves: MOVE_ITERATIONS },
        ...{ frequent: SEARCH_FREQUENT, rare: SEARCH_RARE },
      },
    );

    // Real keys in the middle of the document, after the synthetic measurements.
    await page.evaluate(() => {
      window.__stilo!.focusAt(0.5);
      window.__stilo!.recordKeys();
    });
    await page.waitForTimeout(500);
    await page.keyboard.type('x'.repeat(KEYS), { delay: KEY_DELAY });
    await page.waitForTimeout(500);
    const slowKeys = await page.evaluate(() => window.__stilo!.keyDurations());
    const keys = [
      ...slowKeys,
      ...Array<number>(Math.max(0, KEYS - slowKeys.length)).fill(EVENT_THRESHOLD),
    ];

    const result: Result = {
      load: round(raw.load),
      getHTML: round(percentile(raw.getHTML, 50)),
      typingP95: round(Math.max(...raw.latency.map((samples) => percentile(samples, 95)))),
      typingMedian: round(percentile(raw.latency.flat(), 50)),
      moveBlockP95: round(percentile(raw.moveBlock, 95)),
      moveBlockMedian: round(percentile(raw.moveBlock, 50)),
      keyToPaintMedian: percentile(keys, 50),
      keyToPaintP95: percentile(keys, 95),
      heapMB: raw.heap === null ? null : round(raw.heap / 1024 / 1024),
      searchFrequent: round(raw.searchFrequent),
      searchRare: round(raw.searchRare),
      searchTypingP95: round(percentile(raw.searchTyping, 95)),
    };
    results[name] = result;
    console.log(name, JSON.stringify(result));
  });
}

// Budgets are checked after every document was measured: one slow metric does not stop the run.
test('budgets', async ({ browser }) => {
  const date = new Date().toISOString();
  mkdirSync('bench/results', { recursive: true });
  const file = `bench/results/${date.replace(/[:.]/g, '-')}.json`;
  const report = { date, browser: `${browser.browserType().name()} ${browser.version()}`, results };
  writeFileSync(file, `${JSON.stringify(report, null, 2)}\n`);

  for (const [name, budget] of Object.entries(BUDGETS)) {
    const result = results[name];
    expect.soft(result, `${name}: measured`).toBeDefined();
    if (!result) continue;
    for (const metric of Object.keys(budget) as Array<keyof Budget>) {
      expect.soft(result[metric], `${name}: ${metric}`).toBeLessThan(budget[metric]);
    }
  }
});
